INSERT INTO `email_notification_events` (`event_key`, `event_label`, `description`, `default_subject`, `default_body`, `sort_order`) VALUES
('FINAL_PAYMENT_COMPLETION', 'Final payment or completion status', 'Sent when a request reaches final payment or completion.', 'Request {{request_number}} - Payment/Completion Update', '<p>Request <strong>{{request_number}}</strong> ({{request_description}}) has reached status <strong>{{current_status}}</strong>.</p><p><a href=\"{{action_link}}\">View Request</a></p>', 110),
('FINANCE_ACTION_REQUIRED', 'Finance action required', 'Sent when Finance needs to verify funds, review a commitment, or process payment.', 'Finance Action Required - {{request_number}}', '<p>Request <strong>{{request_number}}</strong> ({{request_description}}) requires Finance action: {{required_action}}.</p><p><a href=\"{{action_link}}\">Review Request</a></p>', 60),
('HOD_BRANCH_HEAD_ACTION_REQUIRED', 'HOD or Branch Head action required', 'Sent when a request needs HOD or Branch Head review/approval.', 'Approval Required: {{request_number}}', '<p>Request <strong>{{request_number}}</strong> ({{request_description}}) from {{requester_name}} requires your approval as {{required_action}}.</p><p>Current status: {{current_status}}</p><p><a href=\"{{action_link}}\">Review Request</a></p>', 30),
('MISSING_DOCUMENT_REMINDER', 'Missing supporting-document reminder', 'Reminder sent when required supporting documents have not been uploaded.', 'Reminder: Missing Supporting Documents - {{request_number}}', '<p>Request <strong>{{request_number}}</strong> is missing required supporting documents. Please upload them as soon as possible.</p><p><a href=\"{{action_link}}\">Upload Documents</a></p>', 80),
('PETTY_CASH_RECONCILIATION_REQUIRED', 'Petty cash reconciliation required', 'Sent when a petty cash advance needs reconciliation documents.', 'Petty Cash Reconciliation Required - {{request_number}}', '<p>Request <strong>{{request_number}}</strong> requires petty cash reconciliation. Due date: {{due_date}}.</p><p><a href=\"{{action_link}}\">Reconcile Now</a></p>', 70),
('PROCUREMENT_REVIEW_REQUIRED', 'Procurement review required', 'Sent when the Procurement Officer needs to review or process a request.', 'Procurement Review Required - {{request_number}}', '<p>Request <strong>{{request_number}}</strong> ({{request_description}}) requires Procurement review.</p><p>Required action: {{required_action}}</p><p><a href=\"{{action_link}}\">Review Request</a></p>', 40),
('REIMBURSEMENT_INVOICE_ACTION_REQUIRED', 'Reimbursement invoice action required', 'Sent when a reimbursement invoice needs review or approval.', 'Reimbursement Invoice Action Required - {{request_number}}', '<p>Request <strong>{{request_number}}</strong> ({{request_description}}) has a reimbursement invoice requiring action: {{required_action}}.</p><p><a href=\"{{action_link}}\">Review Invoice</a></p>', 90),
('REQUEST_APPROVED_REJECTED', 'Request approved or rejected', 'Sent when a request is approved or declined.', 'Request {{request_number}} - {{current_status}}', '<p>Request <strong>{{request_number}}</strong> ({{request_description}}) submitted by {{requester_name}} is now <strong>{{current_status}}</strong>.</p><p><a href=\"{{action_link}}\">View Request</a></p>', 100),
('REQUEST_RETURNED_FOR_CORRECTION', 'Request returned for correction', 'Sent when a request is sent back to the requester for edits.', 'Action Required: Request {{request_number}} Returned For Correction', '<p>Request <strong>{{request_number}}</strong> ({{request_description}}) has been returned to {{requester_name}} for correction.</p><p>Required action: {{required_action}}</p><p><a href=\"{{action_link}}\">View Request</a></p>', 20),
('REQUEST_SUBMITTED', 'New request submitted', 'Sent when a requester submits a new procurement request for approval.', 'New Request Submitted - {{request_number}}', '<p>A new procurement request <strong>{{request_number}}</strong> ({{request_description}}) has been submitted by {{requester_name}} and requires your action.</p><p>Current status: {{current_status}}</p><p><a href=\"{{action_link}}\">{{required_action}}</a></p>', 10),
('VENDOR_QUOTATION_ACTION_REQUIRED', 'Vendor or quotation action required', 'Sent when a vendor quote requires review, selection, or upload.', 'Vendor/Quotation Action Required - {{request_number}}', '<p>Request <strong>{{request_number}}</strong> involving vendor <strong>{{vendor_name}}</strong> requires action: {{required_action}}.</p><p><a href=\"{{action_link}}\">View Request</a></p>', 50);
