DELIMITER $$
CREATE TRIGGER `trg_block_commitment_before_acceptance` BEFORE INSERT ON `commitments` FOR EACH ROW BEGIN
    DECLARE acc_status VARCHAR(20);

    IF NEW.rfq_id IS NOT NULL THEN

        SELECT acceptance_status
        INTO acc_status
        FROM rfqs
        WHERE rfq_id = NEW.rfq_id
        LIMIT 1;

        IF acc_status IS NULL OR acc_status <> 'ACCEPTED' THEN
            SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Vendor acceptance required before commitment';
        END IF;

    END IF;

END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_one_original_commitment` BEFORE INSERT ON `commitments` FOR EACH ROW BEGIN
    IF NEW.commitment_type = 'ORIGINAL' THEN
        IF EXISTS (
            SELECT 1
            FROM commitments
            WHERE request_id = NEW.request_id
              AND commitment_type = 'ORIGINAL'
        ) THEN
            SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Only one ORIGINAL commitment is allowed per request';
        END IF;
    END IF;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_one_original_commitment_update` BEFORE UPDATE ON `commitments` FOR EACH ROW BEGIN
    IF NEW.commitment_type = 'ORIGINAL'
       AND OLD.commitment_type <> 'ORIGINAL' THEN

        IF EXISTS (
            SELECT 1
            FROM commitments
            WHERE request_id = NEW.request_id
              AND commitment_type = 'ORIGINAL'
              AND commitment_id <> OLD.commitment_id
        ) THEN
            SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Only one ORIGINAL commitment is allowed per request';
        END IF;
    END IF;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_prevent_orphaned_non_po_commitment` BEFORE INSERT ON `commitments` FOR EACH ROW BEGIN
    DECLARE rfq_count INT DEFAULT 0;
    DECLARE request_workflow_path VARCHAR(50) DEFAULT NULL;
    DECLARE request_type VARCHAR(50) DEFAULT NULL;
    
    -- Only validate for ORIGINAL commitments (not supplementary)
    IF NEW.commitment_type = 'ORIGINAL' THEN
        -- Check if this is a non-PO commitment (po_required='NO')
        IF NEW.po_required = 'NO' THEN
            -- Get request details: type and workflow_path
            SELECT pr.request_type, pr.workflow_path
            INTO request_type, request_workflow_path
            FROM procurement_requests pr
            WHERE pr.request_id = NEW.request_id
            LIMIT 1;
            
            -- Count RFQs for this request
            SELECT COUNT(*)
            INTO rfq_count
            FROM rfqs
            WHERE request_id = NEW.request_id;
            
            -- For REGULAR requests in skip-RFQ path (no RFQ exists),
            -- ensure workflow_path is explicitly set to NON_PO_SKIP_RFQ
            IF request_type = 'REGULAR' 
               AND rfq_count = 0
               AND (request_workflow_path IS NULL OR request_workflow_path = 'STANDARD')
            THEN
               SIGNAL SQLSTATE '45000' 
               SET MESSAGE_TEXT = 'Cannot create non-PO commitment without setting workflow_path to NON_PO_SKIP_RFQ for skip-RFQ requests';
            END IF;
        END IF;
    END IF;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_require_quote_approval_for_commitment` BEFORE INSERT ON `commitments` FOR EACH ROW BEGIN
    DECLARE requestor_status VARCHAR(50);
    DECLARE branch_head_status VARCHAR(50);

    IF NEW.rfq_id IS NOT NULL AND NEW.selected_quote_id IS NOT NULL THEN
        -- Read-only lookup; does not modify `rfqs`
        SELECT requestor_spec_review_status, branch_head_approval_status
          INTO requestor_status, branch_head_status
          FROM rfqs
         WHERE rfq_id = NEW.rfq_id
         LIMIT 1;

        IF requestor_status IS NULL OR requestor_status != 'APPROVED' THEN
            SIGNAL SQLSTATE '45000'
                SET MESSAGE_TEXT = 'Cannot create commitment: Requestor specification confirmation not approved';
        END IF;

        IF branch_head_status IS NULL OR branch_head_status != 'APPROVED' THEN
            SIGNAL SQLSTATE '45000'
                SET MESSAGE_TEXT = 'Cannot create commitment: Branch Head approval not granted';
        END IF;
    END IF;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_require_quote_review_for_commitment` BEFORE INSERT ON `commitments` FOR EACH ROW BEGIN
    DECLARE review_status VARCHAR(50);
    DECLARE quote_id INT;

    -- If this commitment is linked to an RFQ
    IF NEW.rfq_id IS NOT NULL AND NEW.selected_quote_id IS NOT NULL THEN
        -- Check if the quote has been marked as approved (meets requirements)
        SELECT review_status
        INTO review_status
        FROM rfq_quotes
        WHERE quote_id = NEW.selected_quote_id
        LIMIT 1;

        -- Allow commitment creation if quote is marked as meeting requirements or no review status set
        -- This gives flexibility for different approval workflows
        IF review_status = 'DOES_NOT_MEET' THEN
            SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Cannot create commitment from quote that does not meet requirements';
        END IF;
    END IF;

END
$$
DELIMITER ;

