  `execution_notes` text DEFAULT NULL,
  `duration_ms` int(11) DEFAULT NULL COMMENT 'Milliseconds to complete'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Audit trail of all cron executions';

