--
-- Structure for view `v_non_po_remediation_audit`
--
DROP TABLE IF EXISTS `v_non_po_remediation_audit`;

CREATE ALGORITHM=UNDEFINED DEFINER=`u153072617_dgc_ipams`@`127.0.0.1` SQL SECURITY DEFINER VIEW `v_non_po_remediation_audit`  AS SELECT `pr`.`request_id` AS `request_id`, `pr`.`request_number` AS `request_number`, `pr`.`status` AS `status`, `pr`.`workflow_path` AS `workflow_path`, `pr`.`created_at` AS `request_created_at`, `c`.`commitment_id` AS `commitment_id`, `c`.`commitment_number` AS `commitment_number`, `c`.`po_required` AS `po_required`, `c`.`is_remediated` AS `is_remediated`, `c`.`remediated_at` AS `remediated_at`, `c`.`created_at` AS `commitment_created_at` FROM (`procurement_requests` `pr` left join `commitments` `c` on(`pr`.`request_id` = `c`.`request_id` and `c`.`commitment_type` = 'ORIGINAL')) WHERE `pr`.`request_type` = 'REGULAR' AND `pr`.`workflow_path` = 'NON_PO_SKIP_RFQ' AND !exists(select 1 from `rfqs` where `rfqs`.`request_id` = `pr`.`request_id` limit 1) ORDER BY `pr`.`created_at` DESC ;

-- --------------------------------------------------------

--
-- Structure for view `v_po_requirement_audit`
--
DROP TABLE IF EXISTS `v_po_requirement_audit`;

CREATE ALGORITHM=UNDEFINED DEFINER=`u153072617_dgc_ipams`@`127.0.0.1` SQL SECURITY DEFINER VIEW `v_po_requirement_audit`  AS SELECT `pr`.`request_id` AS `request_id`, `pr`.`request_number` AS `request_number`, `pr`.`request_type` AS `request_type`, `pr`.`status` AS `status`, `pr`.`work_performed` AS `work_performed`, `pr`.`goods_delivered` AS `goods_delivered`, CASE WHEN `pr`.`work_performed` = 1 AND `pr`.`goods_delivered` = 1 THEN 'NO' ELSE 'YES' END AS `derived_po_required`, `c`.`commitment_id` AS `commitment_id`, `c`.`po_required` AS `actual_po_required`, CASE WHEN `pr`.`work_performed` = 1 AND `pr`.`goods_delivered` = 1 AND `c`.`po_required` = 'NO' THEN 'CORRECT' WHEN `pr`.`work_performed` = 1 AND `pr`.`goods_delivered` = 1 AND `c`.`po_required` = 'YES' THEN 'MISMATCH: Flags say NO but commitment says YES' WHEN (`pr`.`work_performed` <> 1 OR `pr`.`goods_delivered` <> 1) AND `c`.`po_required` = 'YES' THEN 'CORRECT' WHEN (`pr`.`work_performed` <> 1 OR `pr`.`goods_delivered` <> 1) AND `c`.`po_required` = 'NO' THEN 'MISMATCH: Flags say YES but commitment says NO' ELSE 'NO_COMMITMENT_YET' END AS `consistency_check`, `pr`.`created_by` AS `created_by`, `pr`.`created_at` AS `created_at`, `pr`.`updated_at` AS `updated_at` FROM (`procurement_requests` `pr` left join `commitments` `c` on(`pr`.`request_id` = `c`.`request_id` and (`c`.`is_remediated` is null or `c`.`is_remediated` = 0))) WHERE `pr`.`request_type` = 'REGULAR' ORDER BY `pr`.`request_id` DESC ;

